from pathlib import Path
import imageio_ffmpeg,subprocess
r=Path(__file__).resolve().parents[1];(r/'audit').mkdir(exist_ok=True);f=imageio_ffmpeg.get_ffmpeg_exe();masked=r/'media-sources/cosmic-background-masked.png'
mask="scale=1920:1080,eq=brightness=-0.015:saturation=0.75,format=rgb24,geq=r='r(X,Y)*clip((hypot(X-960,Y-540)-240)/18,0,1)':g='g(X,Y)*clip((hypot(X-960,Y-540)-240)/18,0,1)':b='b(X,Y)*clip((hypot(X-960,Y-540)-240)/18,0,1)'"
with (r/'audit/render-stars.log').open('w') as log:
 subprocess.run([f,'-y','-i',str(r/'media-sources/cosmic-background-v1.png'),'-vf',mask,'-frames:v','1',str(masked)],stdout=log,stderr=log,check=True)
 filters="[0:v]scale=1920:1080:force_original_aspect_ratio=increase,crop=1920:1080,setsar=1,format=gbrp[hole];[1:v]format=gbrp[stars];[stars][hole]blend=all_mode=screen[space];[2:v]format=rgba,scale=500:-1,rotate='0.055*sin(2*PI*t/32)':ow=560:oh=420:c=none[craft];[space][craft]overlay=x='-w-80+(W+2*w+160)*t/32':y='H*(0.78-0.16*t/32)-h/2':eval=frame:format=auto[scene];[3:v]format=rgba,split=3[a][b][c];[a]scale=76:-1,rotate='2*PI*t/32':ow=100:oh=100:c=none[d1];[b]scale=42:-1,rotate='-2*PI*t/32':ow=60:oh=60:c=none[d2];[c]scale=25:-1,rotate='2*PI*t/32+1.2':ow=36:oh=36:c=none[d3];[scene][d1]overlay=x='170+70*sin(2*PI*t/32)':y='870+36*cos(2*PI*t/32)':eval=frame:format=auto[s1];[s1][d2]overlay=x='1660+65*sin(2*PI*t/32+1)':y='180+30*cos(2*PI*t/32+1)':eval=frame:format=auto[s2];[s2][d3]overlay=x='1500+50*cos(2*PI*t/32)':y='940+22*sin(2*PI*t/32)':eval=frame:format=auto,format=yuv420p[out]"
 subprocess.run([f,'-y','-stream_loop','-1','-i',str(r/'media-sources/black-hole-seamless-gold-60.mp4'),'-loop','1','-framerate','60','-i',str(masked),'-loop','1','-framerate','60','-i',str(r/'media-sources/cinematic-craft-v1.png'),'-loop','1','-framerate','60','-i',str(r/'media-sources/asteroid-fragment-v1.png'),'-filter_complex',filters,'-map','[out]','-t','32','-an','-c:v','libx264','-profile:v','high','-level:v','4.2','-preset','fast','-crf','20','-pix_fmt','yuv420p','-movflags','+faststart',str(r/'neo/assets/neo/video/cinematic-black-hole-v3.mp4')],stdout=log,stderr=log,check=True)
print('Starfield/debris cinematic loop rendered')
